<template>
  <div class="page"><AppNav />
    <main class="collab">
      <aside class="side panel">
        <button class="primary wide" @click="createDialog = true">＋ 创建学习群</button>
        <div class="side-title"><b>学习协作</b><button @click="friendDialog = true">添加好友</button></div>
        <p class="label">我的会话</p>
        <button v-for="item in conversations" :key="item.id" class="conversation" :class="{ active: item.id === currentId }" @click="open(item.id)"><span>{{ item.type === 'group' ? '◌' : '◉' }}</span><div><b>{{ item.title }}</b><small>{{ item.last_message || '还没有消息' }}</small></div></button>
        <p class="label">我的学习伙伴</p>
        <div v-for="friend in friends" :key="friend.id" class="friend"><button class="avatar tiny" @click="profile(friend.id)">{{ friend.avatar }}</button><span>{{ friend.name }}<small>{{ friend.college }}</small></span><button class="text" @click="privateChat(friend.id)">私聊</button></div>
        <p v-if="requests.length" class="label">新的好友申请</p>
        <div v-for="request in requests" :key="request.id" class="request">{{ request.name }}<button @click="accept(request.id)">接受</button></div>
      </aside>
      <section class="chat panel">
        <template v-if="current">
          <header><div><span class="eyebrow">{{ current.type === 'group' ? 'STUDY GROUP' : 'PRIVATE CHAT' }}</span><h1>{{ current.title }}</h1><p>{{ current.member_count }} 位成员 · {{ current.type === 'group' ? '共同制定复习清单、分工与交流' : '与学习伙伴一对一交流' }}</p></div><div class="header-actions" v-if="current.type === 'group'"><button class="soft" @click="membersDialog = true">成员与 Agent</button><button v-if="isOwner" class="soft" @click="agentRequestsDialog = true">审批 Agent <em v-if="agentRequests.length">{{ agentRequests.length }}</em></button></div></header>
          <div class="agent-bar" v-if="current.type === 'group' && myAgentInGroup"><span class="agent-mark">{{ meMember?.agent_avatar || '✦' }}</span><b>{{ meMember?.agent_name || '我的 Agent' }}</b><span>已获准进入本群</span><el-switch :model-value="Boolean(meMember?.agent_auto_reply)" @change="toggleMyAgent" active-text="实时参与偏好" inactive-text="仅旁听" /></div>
          <div class="messages"><article v-for="message in messages" :key="message.id" :class="{ mine: message.sender_id === me.id && message.sender_type === 'user', agent: message.sender_type === 'agent' }"><button class="avatar" @click="profile(message.profile_user_id, message.sender_type === 'agent')">{{ message.sender_avatar }}</button><div><button class="sender" @click="profile(message.profile_user_id, message.sender_type === 'agent')">{{ message.sender_id === me.id && message.sender_type === 'user' ? '我' : message.sender_name }}</button><p>{{ message.content }}</p></div></article><div v-if="!messages.length" class="empty">开始一段有目标的学习讨论吧。</div></div>
          <form @submit.prevent="send"><input v-model="input" maxlength="2000" placeholder="输入学习讨论内容" /><button class="primary">发送</button></form>
        </template><div v-else class="no-chat"><div>◌</div><h2>选择一个学习会话</h2><p>添加伙伴后，可以发起私聊或创建复习群。</p></div>
      </section>
    </main>
    <el-dialog v-model="createDialog" title="创建学习群" width="440px"><el-form label-position="top"><el-form-item label="群名称"><el-input v-model="group.title" placeholder="如：数据结构期末复习小组" /></el-form-item><el-form-item label="邀请学习伙伴"><el-select v-model="group.member_ids" multiple style="width:100%"><el-option v-for="f in friends" :key="f.id" :label="f.name + ' · ' + f.college" :value="f.id" /></el-select></el-form-item></el-form><template #footer><button class="primary" @click="createGroup">创建群聊</button></template></el-dialog>
    <el-dialog v-model="friendDialog" title="添加学习伙伴" width="440px"><el-input v-model="search" placeholder="输入姓名或学号搜索" @input="findUsers" /><div v-for="user in found" :key="user.id" class="found"><button class="avatar" @click="profile(user.id)">{{ user.avatar }}</button><div><b>{{ user.name }}</b><small>{{ user.student_id }} · {{ user.college }}</small></div><button @click="requestFriend(user.id)">添加</button></div></el-dialog>
    <el-dialog v-model="membersDialog" title="群成员与 Agent" width="520px"><div v-for="m in members" :key="m.id" class="member"><button class="avatar" @click="profile(m.id)">{{ m.avatar }}</button><div class="member-name"><button class="sender" @click="profile(m.id)">{{ m.name }}</button><small>{{ m.college }}</small></div><template v-if="m.agent_in_group"><button class="avatar agent-avatar" @click="profile(m.id, true)">{{ m.agent_avatar }}</button><button class="sender" @click="profile(m.id, true)">{{ m.agent_name }}</button></template></div><div v-if="isOwner" class="invite"><el-select v-model="inviteFriendId" placeholder="选择尚未入群的好友"><el-option v-for="f in availableFriends" :key="f.id" :label="f.name" :value="f.id" /></el-select><button class="primary" @click="inviteMember">邀请好友</button></div><button v-else-if="!myAgentInGroup" class="primary" @click="requestMyAgent">邀请我的 Agent 入群（群主审批）</button></el-dialog>
    <el-dialog v-model="agentRequestsDialog" title="等待审批的 Agent" width="470px"><div v-if="!agentRequests.length" class="empty">暂无待审批申请。</div><div v-for="r in agentRequests" :key="r.id" class="request-line"><span>{{ r.agent_avatar }} <b>{{ r.agent_name }}</b> · {{ r.name }} 的 Agent</span><span><button class="soft" @click="handleAgentRequest(r.id, 'reject')">拒绝</button><button class="primary" @click="handleAgentRequest(r.id, 'approve')">同意</button></span></div></el-dialog>
  </div>
</template>
<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import AppNav from '../components/AppNav.vue'
import { api, post } from '../utils/api'
const router = useRouter(); const conversations = ref([]), friends = ref([]), requests = ref([]), messages = ref([]), members = ref([]), agentRequests = ref([]); const currentId = ref(null), input = ref(''), createDialog = ref(false), friendDialog = ref(false), membersDialog = ref(false), agentRequestsDialog = ref(false), search = ref(''), found = ref([]), inviteFriendId = ref(null), group = ref({ title: '', member_ids: [] }); let timer
const me = computed(() => JSON.parse(localStorage.getItem('user') || '{}')); const current = computed(() => conversations.value.find(x => x.id === currentId.value)); const isOwner = computed(() => current.value?.owner_id === me.value.id); const meMember = computed(() => members.value.find(m => m.id === me.value.id)); const myAgentInGroup = computed(() => Boolean(meMember.value?.agent_in_group)); const availableFriends = computed(() => friends.value.filter(f => !members.value.some(m => m.id === f.id)))
async function load () { [conversations.value, friends.value, requests.value] = await Promise.all([api('/conversations'), api('/friends'), api('/friend-requests')]); if (conversations.value[0] && !currentId.value) await open(conversations.value[0].id) }
async function open (id) { currentId.value = id; await refreshCurrent() }
async function refreshCurrent () { if (!currentId.value) return; messages.value = await api(`/conversations/${currentId.value}/messages`); if (current.value?.type === 'group') { members.value = await api(`/conversations/${currentId.value}/members`); agentRequests.value = isOwner.value ? await api(`/conversations/${currentId.value}/agent-requests`) : [] } else members.value = [] }
async function send () { if (!input.value.trim()) return; try { await post(`/conversations/${currentId.value}/messages`, { content: input.value }); input.value = ''; await refreshCurrent(); await load() } catch (e) { ElMessage.error(e.message) } }
async function privateChat (friendId) { try { const data = await post('/conversations/private', { friend_id: friendId }); await load(); await open(data.id) } catch (e) { ElMessage.error(e.message) } }
async function createGroup () { try { const data = await post('/conversations', group.value); createDialog.value = false; group.value = { title: '', member_ids: [] }; await load(); await open(data.id) } catch (e) { ElMessage.error(e.message) } }
async function findUsers () { found.value = search.value.trim() ? await api(`/users/search?q=${encodeURIComponent(search.value)}`) : [] }
async function requestFriend (id) { try { await post('/friend-requests', { user_id: id }); ElMessage.success('好友申请已发送') } catch (e) { ElMessage.error(e.message) } }
async function accept (id) { try { await post(`/friend-requests/${id}/accept`, {}); await load(); ElMessage.success('已成为好友') } catch (e) { ElMessage.error(e.message) } }
async function inviteMember () { try { await post(`/conversations/${currentId.value}/members`, { user_id: inviteFriendId.value }); inviteFriendId.value = null; await refreshCurrent(); await load(); ElMessage.success('已邀请好友入群') } catch (e) { ElMessage.error(e.message) } }
async function requestMyAgent () { try { await post(`/conversations/${currentId.value}/agent-requests`, {}); await refreshCurrent(); ElMessage.success('已提交申请，等待群主审批') } catch (e) { ElMessage.error(e.message) } }
async function handleAgentRequest (id, action) { try { await api(`/conversations/${currentId.value}/agent-requests/${id}`, { method: 'PATCH', body: JSON.stringify({ action }) }); await refreshCurrent(); ElMessage.success(action === 'approve' ? '已同意 Agent 入群' : '已拒绝申请') } catch (e) { ElMessage.error(e.message) } }
async function toggleMyAgent (autoReply) { try { const data = await api(`/conversations/${currentId.value}/my-agent`, { method: 'PATCH', body: JSON.stringify({ auto_reply: autoReply }) }); ElMessage.success(data.message); await refreshCurrent() } catch (e) { ElMessage.error(e.message) } }
function profile (id, agent = false) { router.push({ path: `/profile/${id}`, query: agent ? { agent: '1' } : {} }) }
onMounted(async () => { try { await load(); timer = setInterval(async () => { try { await refreshCurrent(); await load() } catch {} }, 4000) } catch (e) { ElMessage.error(e.message) } }); onBeforeUnmount(() => clearInterval(timer))
</script>
<style scoped>
