ca;color:#9f4c2b;border-radius:50%;width:34px;height:34px;display:inline-grid;place-items:center;cursor:pointer;font-size:17px}.avatar.tiny{width:27px;height:27px;font-size:14px}.agent-avatar{background:#ecdff4;color:#745288}.messages{flex:1;background:#fffaf6;border-top:1px solid #f2e5dc;border-bottom:1px solid #f2e5dc;padding:20px 28px;overflow:auto}.messages article{max-width:78%;margin:12px 0;display:flex;gap:8px;align-items:flex-start}.messages article.mine{margin-left:auto;flex-direction:row-reverse}.messages article.agent .avatar{background:#ecdff4;color:#745288}.sender{border:0;background:transparent;padding:0;color:#a8806c;font-size:12px;cursor:pointer;text-align:left}.messages p{margin:4px 0;background:#f9ece3;border-radius:14px 14px 14px 3px;padding:10px 13px;color:#684839;text-align:left;line-height:1.55;white-space:pre-wrap}.messages .mine p{background:#c96d42;color:#fff;border-radius:14px 14px 3px 14px}.chat form{display:flex;gap:9px;padding:15px 20px}.chat input{flex:1;border:1px solid #ead8cd;border-radius:13px;padding:11px;font:inherit}.no-chat,.empty{text-align:center;margin:auto;color:#a08475}.no-chat>div{font-size:50px;color:#c96d42}.found{border-bottom:1px solid #f2e5dc}.found div{flex:1}.found>button:last-child{border:0;background:#fff0e4;color:#ad5938;border-radius:9px;padding:6px;cursor:pointer}.member-name{flex:1}.invite{display:flex;gap:8px;border-top:1px solid #f2e5dc;padding-top:15px;margin-top:8px}.invite .el-select{flex:1}.request-line{justify-content:space-between;border-bottom:1px solid #f2e5dc}.request-line span:last-child{display:flex;gap:7px}@media(max-width:850px){.collab{grid-template-columns:1fr;padding:15px}.side{display:none}.chat{min-height:calc(100vh - 105px)}.agent-bar{padding:9px 14px}.chat header{padding:19px}.messages{padding:16px}}
</style>
